"use client";
import { cn } from "@/lib/utils";
import { useState, useRef } from "react";
import { ArrowRight, Check, Search, X } from "lucide-react";
import { panel } from "@/lib/takt-surface";
export function SpringyInput({
  className,
  placeholder = "Search project",
  onChange,
  onSubmit,
}: {
  className?: string;
  placeholder?: string;
  onChange?: (text: string) => void;
  onSubmit?: (query: string) => void;
}) {
  const [text, setText] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  function update(value: string) {
    setText(value);
    setSubmitted(false);
    onChange?.(value);
  }
  return (
    <form
      className={cn(
        panel +
          " flex w-64 items-center gap-2 px-3 py-2 motion-safe:transition-colors has-[input:focus]:border-foreground/55 forced-colors:has-[input:focus]:outline-2 forced-colors:has-[input:focus]:outline-[Highlight]",
        className,
      )}
      onSubmit={(e) => {
        e.preventDefault();
        if (!text.trim()) return;
        setSubmitted(true);
        onSubmit?.(text.trim());
      }}
    >
      <span
        key={text.length}
        className="shrink-0 text-muted-foreground motion-safe:animate-in motion-safe:zoom-in-90"
      >
        <Search size={17} />
      </span>
      <input
        ref={input}
        type="search"
        className="h-8 min-w-0 flex-1 bg-transparent text-sm focus:outline-none! [&::-webkit-search-cancel-button]:hidden"
        aria-label={placeholder}
        placeholder={placeholder}
        value={text}
        onChange={(e) => update(e.target.value)}
      />
      {text && (
        <button
          type="button"
          aria-label="Clear"
          className="rounded-md p-1 text-muted-foreground"
          onClick={() => {
            update("");
            input.current?.focus();
          }}
        >
          <X size={13} />
        </button>
      )}
      <button
        type="submit"
        disabled={!text.trim()}
        aria-label="Find"
        className="grid size-7 place-items-center rounded-lg bg-primary text-primary-foreground disabled:opacity-30"
      >
        {submitted ? (
          <Check
            size={14}
            className="motion-safe:animate-in motion-safe:zoom-in-75"
          />
        ) : (
          <ArrowRight size={14} />
        )}
      </button>
      <span className="sr-only" role="status">
        {submitted ? "Request received" : ""}
      </span>
    </form>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
